import React from 'react';
import { Receipt, Info } from 'lucide-react';
import { CryptoToken } from '../../types/crypto';

interface PaypalWithdrawalSummaryProps {
  amount: number;
  token: CryptoToken;
  serviceFee: number;
  paypalFee: number;
  total: number;
  tokenPrice: number;
}

export default function PaypalWithdrawalSummary({
  amount,
  token,
  serviceFee,
  paypalFee,
  total,
  tokenPrice
}: PaypalWithdrawalSummaryProps) {
  const amountUSD = amount * tokenPrice;
  const serviceFeeUSD = serviceFee * tokenPrice;
  const paypalFeeUSD = paypalFee * tokenPrice;
  const totalUSD = total * tokenPrice;

  return (
    <div className="bg-slate-900/50 rounded-xl p-4">
      <div className="flex items-center mb-4">
        <Receipt className="w-5 h-5 text-violet-400 mr-2" />
        <h3 className="text-lg font-semibold">Transaction Summary</h3>
      </div>

      <div className="space-y-3">
        <div className="flex justify-between text-sm">
          <span className="text-gray-400">Amount</span>
          <div className="text-right">
            <div>{amount.toFixed(8)} {token.symbol}</div>
            <div className="text-xs text-gray-400">≈ ${amountUSD.toFixed(2)}</div>
          </div>
        </div>

        <div className="flex justify-between text-sm">
          <span className="text-gray-400">Service Fee (1%)</span>
          <div className="text-right text-red-400">
            <div>-{serviceFee.toFixed(8)} {token.symbol}</div>
            <div className="text-xs">≈ -${serviceFeeUSD.toFixed(2)}</div>
          </div>
        </div>

        <div className="flex justify-between text-sm">
          <span className="text-gray-400">PayPal Fee</span>
          <div className="text-right text-red-400">
            <div>-{paypalFee.toFixed(8)} {token.symbol}</div>
            <div className="text-xs">≈ -$5.00</div>
          </div>
        </div>

        <div className="flex justify-between text-sm font-medium">
          <span className="text-gray-400">You Receive</span>
          <div className="text-right text-green-400">
            <div>{total.toFixed(8)} {token.symbol}</div>
            <div className="text-xs">≈ ${totalUSD.toFixed(2)}</div>
          </div>
        </div>

        <div className="mt-4 bg-violet-500/10 border border-violet-500/20 rounded-lg p-3">
          <div className="flex items-center text-violet-400 text-sm mb-1">
            <Info className="w-4 h-4 mr-1" />
            <span>Processing Time</span>
          </div>
          <p className="text-xs text-gray-400">
            PayPal withdrawals are typically processed within 24 hours during business days.
          </p>
        </div>
      </div>
    </div>
  );
}