import React, { useState } from 'react';
import { AlertTriangle, Shield, Info, Mail } from 'lucide-react';
import CryptoSelector from '../withdrawal/CryptoSelector';
import { useCryptoPrices } from '../../hooks/useCryptoPrices';
import { tokens } from '../../data/tokens';
import { validateEscrowAmount } from '../../utils/validation';
import { generateEscrowId, validateEmail } from '../../utils/escrow';
import EscrowModal from './EscrowModal';
import EscrowNotice from './EscrowNotice';
import EmailInputs from './EmailInputs';
import EscrowSummary from './EscrowSummary';

export default function EscrowForm() {
  const { prices, loading } = useCryptoPrices();
  const [selectedToken, setSelectedToken] = useState(tokens[0]);
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [sellerAddress, setSellerAddress] = useState('');
  const [buyerEmail, setBuyerEmail] = useState('');
  const [sellerEmail, setSellerEmail] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleAmountChange = (value: string) => {
    const numAmount = parseFloat(value);
    const tokenPrice = prices[selectedToken.symbol] || 0;
    const amountUSD = numAmount * tokenPrice;
    
    const validationError = validateEscrowAmount(amountUSD);
    setError(validationError);
    setAmount(value);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    
    if (error) {
      alert(error);
      return;
    }
    
    if (!sellerAddress) {
      alert('Please enter the seller\'s address');
      return;
    }

    if (!description) {
      alert('Please enter a description of the goods or services');
      return;
    }

    if (!validateEmail(buyerEmail)) {
      alert('Please enter a valid buyer email address');
      return;
    }

    if (!validateEmail(sellerEmail)) {
      alert('Please enter a valid seller email address');
      return;
    }

    setIsModalOpen(true);
  };

  if (loading) {
    return (
      <div className="text-center py-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-violet-500 mx-auto"></div>
        <p className="mt-4 text-gray-400">Loading cryptocurrency data...</p>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto">
      <div className="bg-slate-800/50 backdrop-blur-xl rounded-2xl p-6 border border-slate-700">
        <div className="flex items-center mb-6">
          <Shield className="w-6 h-6 text-violet-400 mr-2" />
          <h2 className="text-xl font-bold">Escrow Payment</h2>
        </div>

        <EscrowNotice />

        {error && (
          <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-4 mb-6 flex items-start">
            <AlertTriangle className="w-5 h-5 text-red-400 mr-2 flex-shrink-0 mt-0.5" />
            <p className="text-red-400 text-sm">{error}</p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <CryptoSelector
            selectedToken={selectedToken}
            onSelect={setSelectedToken}
            prices={prices}
          />

          <div>
            <label className="block text-sm text-gray-400 mb-2">Amount</label>
            <div className="relative">
              <input
                type="number"
                value={amount}
                onChange={(e) => handleAmountChange(e.target.value)}
                placeholder={`Enter amount in ${selectedToken.symbol}`}
                className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:border-violet-500 transition-colors"
              />
              {amount && (
                <div className="mt-1 text-sm text-gray-400">
                  ≈ ${((parseFloat(amount) || 0) * (prices[selectedToken.symbol] || 0)).toFixed(2)}
                </div>
              )}
            </div>
          </div>

          <EmailInputs
            buyerEmail={buyerEmail}
            sellerEmail={sellerEmail}
            onBuyerEmailChange={setBuyerEmail}
            onSellerEmailChange={setSellerEmail}
          />

          <div>
            <label className="block text-sm text-gray-400 mb-2">Seller's Address</label>
            <input
              type="text"
              value={sellerAddress}
              onChange={(e) => setSellerAddress(e.target.value)}
              placeholder={`Enter the seller's ${selectedToken.symbol} address`}
              className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:border-violet-500 transition-colors"
            />
          </div>

          <div>
            <label className="block text-sm text-gray-400 mb-2">Description</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Describe the goods or services you're paying for"
              className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:border-violet-500 transition-colors min-h-[100px]"
            />
          </div>

          <EscrowSummary
            amount={parseFloat(amount) || 0}
            token={selectedToken}
            tokenPrice={prices[selectedToken.symbol] || 0}
          />

          <button
            type="submit"
            disabled={!!error || !amount}
            className={`w-full py-4 px-6 rounded-xl font-semibold transition-colors ${
              error || !amount
                ? 'bg-slate-600 cursor-not-allowed'
                : 'bg-violet-600 hover:bg-violet-700'
            }`}
          >
            {error ? 'Invalid Amount' : 'Create Escrow'}
          </button>
        </form>
      </div>

      <EscrowModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        token={selectedToken}
        amount={parseFloat(amount) || 0}
        sellerAddress={sellerAddress}
        description={description}
        escrowId={generateEscrowId()}
        buyerEmail={buyerEmail}
        sellerEmail={sellerEmail}
      />
    </div>
  );
}